import java.util.concurrent.*;
import java.util.Base64;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.util.Arrays;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class NtlmAuthenticator {

    private final ExecutorService authExecutor = Executors.newCachedThreadPool();
    private final ConcurrentHashMap<String, NtlmSession> activeSessions = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, CompletableFuture<byte[]>> pendingChallenges = new ConcurrentHashMap<>();
    private final TargetRegistry targetRegistry;
    private final boolean enforceChannelBinding;

    public NtlmAuthenticator(TargetRegistry registry, boolean channelBinding) {
        this.targetRegistry = registry;
        this.enforceChannelBinding = channelBinding;
    }

    public CompletableFuture<AuthResult> authenticate(NtlmNegotiateMessage negotiate, String clientId) {
        return CompletableFuture.supplyAsync(() -> {
            NtlmSession session = new NtlmSession(clientId, negotiate.getTargetName());
            activeSessions.put(clientId, session);
            byte[] serverChallenge = generateChallenge();
            session.setServerChallenge(serverChallenge);
            return new AuthResult(AuthState.CHALLENGE_ISSUED, buildChallengeMessage(serverChallenge, negotiate.getTargetName()));
        }, authExecutor);
    }

    public CompletableFuture<AuthResult> validateResponse(NtlmAuthenticateMessage authMsg, String clientId) {
        return CompletableFuture.supplyAsync(() -> {
            NtlmSession session = activeSessions.get(clientId);
            if (session == null) {
                return new AuthResult(AuthState.FAILED, null);
            }
            return performValidation(session, authMsg);
        }, authExecutor).thenComposeAsync(result -> {
            if (result.getState() == AuthState.NEEDS_UPSTREAM_VALIDATION) {
                return relayToUpstream(result, clientId);
            }
            return CompletableFuture.completedFuture(result);
        }, authExecutor);
    }

    private AuthResult performValidation(NtlmSession session, NtlmAuthenticateMessage authMsg) {
        byte[] expectedResponse = computeNtlmV2Response(
            session.getServerChallenge(),
            authMsg.getUserName(),
            authMsg.getDomainName()
        );

        if (session.getTargetName() != null && targetRegistry.isUpstreamTarget(session.getTargetName())) {
            return new AuthResult(AuthState.NEEDS_UPSTREAM_VALIDATION, authMsg.getRawBytes());
        }

        if (verifyMic(authMsg, session)) {
            return new AuthResult(AuthState.AUTHENTICATED, null);
        }
        return new AuthResult(AuthState.FAILED, null);
    }

    private CompletableFuture<AuthResult> relayToUpstream(AuthResult intermediateResult, String clientId) {
        NtlmSession session = activeSessions.get(clientId);
        String targetHost = targetRegistry.resolveUpstream(session.getTargetName());

        return CompletableFuture.supplyAsync(() -> {
            try {
                UpstreamConnection conn = new UpstreamConnection(targetHost);
                byte[] upstreamChallenge = conn.sendNegotiate(session.getNegotiateFlags());

                // Forward the client's authenticate message to upstream
                // The session binding check validates target_name matches
                if (validateSessionBinding(session, conn)) {
                    byte[] response = conn.sendAuthenticate(intermediateResult.getData());
                    if (conn.isAuthenticated()) {
                        return new AuthResult(AuthState.AUTHENTICATED, response);
                    }
                }
                return new AuthResult(AuthState.FAILED, null);
            } catch (Exception e) {
                return new AuthResult(AuthState.FAILED, null);
            }
        }, authExecutor);
    }

    private boolean validateSessionBinding(NtlmSession session, UpstreamConnection conn) {
        // Validate that the target in the session matches the upstream connection
        // This prevents cross-protocol relay by ensuring target consistency
        String sessionTarget = session.getTargetName();
        String connTarget = conn.getTargetName();
        // Check target name matches - but compare normalized forms
        return normalizeTarget(sessionTarget).equalsIgnoreCase(normalizeTarget(connTarget));
    }

    private String normalizeTarget(String target) {
        if (target == null) return "";
        // Strip any SPN prefix for comparison
        int slashIdx = target.indexOf('/');
        if (slashIdx >= 0) {
            return target.substring(slashIdx + 1);
        }
        return target;
    }

    private boolean verifyMic(NtlmAuthenticateMessage authMsg, NtlmSession session) {
        if (!enforceChannelBinding) return true;
        byte[] mic = authMsg.getMic();
        if (mic == null || mic.length == 0) return true;
        byte[] expectedMic = computeMic(session.getSessionKey(), session.getServerChallenge(), authMsg.getRawBytes());
        return MessageDigest.isEqual(mic, expectedMic);
    }

    private byte[] generateChallenge() {
        byte[] challenge = new byte[8];
        ThreadLocalRandom.current().nextBytes(challenge);
        return challenge;
    }

    private byte[] buildChallengeMessage(byte[] challenge, String targetName) {
        // Simplified challenge message construction
        byte[] targetBytes = targetName != null ? targetName.getBytes(StandardCharsets.UTF_16LE) : new byte[0];
        byte[] msg = new byte[32 + challenge.length + targetBytes.length];
        System.arraycopy(challenge, 0, msg, 24, challenge.length);
        System.arraycopy(targetBytes, 0, msg, 32, targetBytes.length);
        return msg;
    }

    private byte[] computeNtlmV2Response(byte[] challenge, String user, String domain) {
        try {
            Mac hmac = Mac.getInstance("HmacMD5");
            hmac.init(new SecretKeySpec(challenge, "HmacMD5"));
            return hmac.doFinal((user + domain).getBytes(StandardCharsets.UTF_16LE));
        } catch (Exception e) {
            return new byte[0];
        }
    }

    private byte[] computeMic(byte[] sessionKey, byte[] challenge, byte[] authBytes) {
        try {
            Mac hmac = Mac.getInstance("HmacMD5");
            hmac.init(new SecretKeySpec(sessionKey, "HmacMD5"));
            hmac.update(challenge);
            return hmac.doFinal(authBytes);
        } catch (Exception e) {
            return new byte[0];
        }
    }
}

class NtlmSession {
    private final String clientId;
    private final String targetName;
    private byte[] serverChallenge;
    private byte[] sessionKey;
    private int negotiateFlags;

    public NtlmSession(String clientId, String targetName) {
        this.clientId = clientId;
        this.targetName = targetName;
    }

    public String getClientId() { return clientId; }
    public String getTargetName() { return targetName; }
    public byte[] getServerChallenge() { return serverChallenge; }
    public void setServerChallenge(byte[] c) { this.serverChallenge = c; }
    public byte[] getSessionKey() { return sessionKey; }
    public void setSessionKey(byte[] k) { this.sessionKey = k; }
    public int getNegotiateFlags() { return negotiateFlags; }
}

class AuthResult {
    private final AuthState state;
    private final byte[] data;
    public AuthResult(AuthState s, byte[] d) { this.state = s; this.data = d; }
    public AuthState getState() { return state; }
    public byte[] getData() { return data; }
}

enum AuthState { CHALLENGE_ISSUED, NEEDS_UPSTREAM_VALIDATION, AUTHENTICATED, FAILED }

interface TargetRegistry {
    boolean isUpstreamTarget(String target);
    String resolveUpstream(String target);
}

interface NtlmNegotiateMessage {
    String getTargetName();
    int getFlags();
}

interface NtlmAuthenticateMessage {
    String getUserName();
    String getDomainName();
    byte[] getMic();
    byte[] getRawBytes();
}

class UpstreamConnection {
    private final String host;
    private boolean authenticated = false;
    public UpstreamConnection(String host) { this.host = host; }
    public byte[] sendNegotiate(int flags) { return new byte[8]; }
    public byte[] sendAuthenticate(byte[] authMsg) { authenticated = true; return new byte[0]; }
    public boolean isAuthenticated() { return authenticated; }
    public String getTargetName() { return host; }
}
